package com.example.facefit

import com.example.facefit.facefit.analysis.FaceAnalyzer
import com.example.facefit.facefit.analysis.FaceShapeFeatures
import org.junit.Assert.*
import org.junit.Test

class FaceShapeFeaturesTest {
    private fun points() = List(478) { i ->
        FaceAnalyzer.LandmarkPoint((0.2 + i % 23 * 0.02).toFloat(),
            (0.15 + i / 23 * 0.025).toFloat())
    }

    @Test fun allTenFeaturesMatchOriginalPythonExtractor() {
        // Generated by the training script's extract_ratios on this exact float32 grid.
        val expected = listOf(0.5605145035885848, 0.8814592823931532, 0.9109671802636011,
            0.8814592861186669, 0.9241768257567272, 1.0484622946411497,
            1.097734387874035, 1.0334761893826045, 0.1633575494100244, 5.981454521528708)
        val actual = FaceShapeFeatures.extract(points(), 640, 960)!!
        assertEquals(10, actual.size)
        expected.forEachIndexed { i, value -> assertEquals(value.toFloat(), actual[i], 0.000002f) }
    }

    @Test fun changingImageEncodingAspectAndUniformScalePreservesPhysicalFeatures() {
        val original = points()
        val expected = FaceShapeFeatures.extract(original, 640, 960)!!
        val landscape = original.map { it.copy(x = it.x * 640f / 960f, y = it.y * 960f / 640f) }
        val actual = FaceShapeFeatures.extract(landscape, 960, 640)!!
        val scaled = FaceShapeFeatures.extract(original, 1280, 1920)!!
        expected.indices.forEach { i ->
            assertEquals(expected[i], actual[i], 0.00001f)
            assertEquals(expected[i], scaled[i], 0.00001f)
        }
    }

    @Test fun missingCollapsedAndNonFiniteLandmarksAreRejected() {
        assertNull(FaceShapeFeatures.extract(emptyList(), 640, 960))
        assertNull(FaceShapeFeatures.extract(points(), 0, 960))
        assertNull(FaceShapeFeatures.extract(List(478) { FaceAnalyzer.LandmarkPoint(0.5f, 0.5f) }, 640, 960))
        val invalid = points().toMutableList().apply { this[150] = this[150].copy(x = Float.NaN) }
        assertNull(FaceShapeFeatures.extract(invalid, 640, 960))
        assertFalse(FaceShapeFeatures.isValid(List(10) { Float.POSITIVE_INFINITY }))
        assertFalse(FaceShapeFeatures.isValid(List(9) { 1f }))
    }
}
